type PerformanceExpectation = {
    perf: number;
    sd: number;
    ci68: [number, number];
    ci95: [number, number];
    ess: number;
    gamesWithOpp: number;
    windowStartRating: number;
    probAboveCurrent: number | null;
    sessionSurprise: number | null;
};

// Floats are compared to 1e-9 by canonicalizing both sides; the port performs
// the exact same double operations, so the rounded values must be identical.
function round9(value: number) {
    return Math.round(value * 1e9) / 1e9;
}

function canonicalPerformance(value: PerformanceExpectation): PerformanceExpectation {
    return {
        ...value,
        sd: round9(value.sd),
        probAboveCurrent: value.probAboveCurrent === null ? null : round9(value.probAboveCurrent),
        sessionSurprise: value.sessionSurprise === null ? null : round9(value.sessionSurprise),
    };
}

function expectPerformance(actual: StatsPerformance | null, expected: PerformanceExpectation) {
    expect(actual).not.toBeNull();
    expect(canonicalPerformance(actual as StatsPerformance)).toEqual(
        canonicalPerformance(expected),
    );
}

afterEach(() => {
    vi.unstubAllGlobals();
    vi.restoreAllMocks();
});

describe("computePerformance golden fidelity vs original smart-bracket.js", () => {
    it("matches the original on mixed results with draws, missing opponents and session gaps", () => {
        const actual = computePerformance(SCENARIO_A_GAMES, { currentRating: 1500, nowSec: NOW });
        expectPerformance(actual, SCENARIO_A_EXPECTED);
    });

    it("matches the original on an all-wins run (prior keeps the estimate finite)", () => {
        const actual = computePerformance(SCENARIO_B_GAMES, { currentRating: 1450, nowSec: NOW });
        expectPerformance(actual, SCENARIO_B_EXPECTED);
    });

    it("nulls probAboveCurrent and sessionSurprise without a current rating", () => {
        const actual = computePerformance(SCENARIO_B_GAMES, { currentRating: null, nowSec: NOW });
        expectPerformance(actual, SCENARIO_B_EXPECTED_NO_CURRENT);
    });

    it("matches the original at the exactly-3-opponent-tagged-games boundary", () => {
        const actual = computePerformance(SCENARIO_C_GAMES, { currentRating: 1520, nowSec: NOW });
        expectPerformance(actual, SCENARIO_C_EXPECTED);
    });

    it("returns null with fewer than 3 opponent-tagged games", () => {
        expect(
            computePerformance(SCENARIO_D_GAMES, { currentRating: 1400, nowSec: NOW }),
        ).toBeNull();
        expect(computePerformance([], { currentRating: 1400, nowSec: NOW })).toBeNull();
    });
});

describe("computePerformanceSeries golden fidelity vs original smart-bracket.js", () => {
    it("matches the original 35-game rolling series (default windowSize 20)", () => {
        const series = computePerformanceSeries(SCENARIO_E_GAMES);
        expect(series.length).toBe(SCENARIO_E_SERIES_DEFAULT.length);
        for (let i = 0; i < series.length; i += 1) {
            expect(series[i].end).toBe(SCENARIO_E_SERIES_DEFAULT[i].end);
            expect(series[i].perf).toBe(SCENARIO_E_SERIES_DEFAULT[i].perf);
            expect(series[i].sd).toBeCloseTo(SCENARIO_E_SERIES_DEFAULT[i].sd, 9);
        }
    });

    it("matches the original with an explicit windowSize of 5", () => {
        const series = computePerformanceSeries(SCENARIO_E_GAMES, { windowSize: 5 });
        expect(series.length).toBe(SCENARIO_E_SERIES_WINDOW_5.length);
        for (let i = 0; i < series.length; i += 1) {
            expect(series[i].end).toBe(SCENARIO_E_SERIES_WINDOW_5[i].end);
            expect(series[i].perf).toBe(SCENARIO_E_SERIES_WINDOW_5[i].perf);
            expect(series[i].sd).toBeCloseTo(SCENARIO_E_SERIES_WINDOW_5[i].sd, 9);
        }
    });
});

describe("computePeriodPerformance", () => {
    it("uses every game in the selected period instead of the latest rolling chart point", () => {
        const games = Array.from({ length: 30 }, (_, index) => ({
            end: NOW - (29 - index) * 12 * 3600,
            start: null,
            rated: true,
            rating: 1500,
            opp: index < 15 ? 1900 : 1100,
            result: (index < 15 ? "win" : "loss") as StatsGameResult,
        }));

        const performance = computePeriodPerformance(games, {
            currentRating: 1500,
            nowSec: NOW,
            windowStart: games[0].end,
            windowEnd: NOW,
        });
        const latestRollingPoint = computePerformanceSeries(games, { windowSize: 20 }).at(-1);

        expect(performance?.gamesWithOpp).toBe(30);
        expect(performance?.perf).toBe(1342);
        expect(latestRollingPoint?.perf).toBe(1048);
        expect(performance?.perf).not.toBe(latestRollingPoint?.perf);
    });
});

describe("computeFormSummary golden fidelity vs original computeSmartBracket", () => {
    it("suppresses streak tilt when the loss streak came against much stronger opponents", () => {
        const actual = computeFormSummary(FORM_F1_GAMES, { currentRating: 1500, nowSec: NOW });
        expect(actual).toEqual(FORM_F1_EXPECTED);
    });

    it("fires tilt via session surprise when quietly losing games it would usually win", () => {
        const actual = computeFormSummary(FORM_F2_GAMES, { currentRating: 1500, nowSec: NOW });
        expect(actual).toEqual(FORM_F2_EXPECTED);
    });

    it("fires tilt from the session net without surprise suppression", () => {
        const actual = computeFormSummary(FORM_F3_GAMES, { currentRating: 1500, nowSec: NOW });
        expect(actual).toEqual(FORM_F3_EXPECTED);
    });

    it("does not tilt when the losing session is older than 12 hours", () => {
        const actual = computeFormSummary(FORM_F4_GAMES, { currentRating: 1500, nowSec: NOW });
        expect(actual).toEqual(FORM_F4_EXPECTED);
    });

    it("only refines tilt through the performance layer when opponents are known", () => {
        const streakLosses: FixtureGame[] = [
            { end: NOW - 2100, start: NOW - 2340, rating: 1508, result: "win", opp: 1900 },
            { end: NOW - 1800, start: NOW - 2040, rating: 1516, result: "win", opp: 1900 },
            { end: NOW - 1500, start: NOW - 1740, rating: 1524, result: "win", opp: 1900 },
            { end: NOW - 1200, start: NOW - 1440, rating: 1516, result: "loss", opp: 1900 },
            { end: NOW - 900, start: NOW - 1140, rating: 1508, result: "loss", opp: 1900 },
            { end: NOW - 600, start: NOW - 840, rating: 1500, result: "loss", opp: 1900 },
        ];
        // Session surprise stays positive -> the loss streak is not tilt.
        const refined = computeFormSummary(streakLosses, { currentRating: 1500, nowSec: NOW });
        expect(refined.tilt).toBe(false);
        // Without opponent ratings there is no performance layer, so the raw
        // streak rule stands.
        const noOpps = streakLosses.map((game) => ({ ...game, opp: null }));
        const raw = computeFormSummary(noOpps, { currentRating: 1500, nowSec: NOW });
        expect(raw.tilt).toBe(true);
    });
});

describe("session and trend helpers", () => {
    it("groups sessions with the 3600s gap on start when present, end otherwise", () => {
        expect(groupSessions(SCENARIO_A_GAMES).map((session) => session.length)).toEqual([4, 4, 4]);
        // start-based gap keeps games together even when ends are far apart...
        const games = [
            { end: 1000, start: null },
            { end: 90000, start: 1500 },
            // ...and a null start falls back to the end-to-end gap.
            { end: 95000, start: null },
        ];
        expect(groupSessions(games).map((session) => session.length)).toEqual([2, 1]);
        expect(groupSessions([])).toEqual([]);
    });

    it("computes recent streaks and handles empty input", () => {
        expect(recentStreak([])).toBeNull();
        expect(
            recentStreak([{ result: "win" }, { result: "loss" }, { result: "loss" }] as {
                result: StatsGameResult;
            }[]),
        ).toEqual({ type: "loss", len: 2 });
    });

    it("returns 0 trend for fewer than 5 games or a degenerate time axis", () => {
        expect(trendPerWeek(SCENARIO_C_GAMES)).toBe(0);
        expect(
            trendPerWeek([
                { end: NOW, rating: 1500 },
                { end: NOW, rating: 1510 },
                { end: NOW, rating: 1520 },
                { end: NOW, rating: 1530 },
                { end: NOW, rating: 1540 },
            ]),
        ).toBe(0);
    });
});

