function stubChessComFetch(nowSec: number) {
    const archivesUrl = "https://api.chess.com/pub/player/StatsGuy/games/archives";
    const monthUrl = "https://api.chess.com/pub/player/statsguy/games/2026/07";
    const olderMonthUrl = "https://api.chess.com/pub/player/statsguy/games/2026/06";
    return stubFetch((url) => {
        if (url === archivesUrl) return { json: { archives: [olderMonthUrl, monthUrl] } };
        if (url === monthUrl) return { json: buildChessComArchive(nowSec) };
        if (url === olderMonthUrl) return { json: { games: [] } };
        return null;
    });
}

describe("fetchStatsGames chess.com normalization", () => {
    it("normalizes archive games with terminations, time controls and openings", async () => {
        const nowSec = Math.floor(Date.now() / 1000);
        stubChessComFetch(nowSec);

        const games = await fetchStatsGames({
            source: "chesscom",
            username: "StatsGuy",
            timeClass: "blitz",
            ratedFilter: "both",
            maxGames: 100,
            maxDays: 30,
            monthsCap: 2,
        });

        expect(games.map((game) => game.termination)).toEqual([
            "checkmate",
            "resign",
            "timeout",
            "draw",
        ]);
        expect(games.map((game) => game.result)).toEqual(["loss", "win", "loss", "draw"]);
        expect(games.map((game) => game.end)).toEqual([
            nowSec - 12000,
            nowSec - 9000,
            nowSec - 6000,
            nowSec - 3000,
        ]);

        const win = games[1];
        expect(win.source).toBe("chesscom");
        expect(win.id).toBe("https://www.chess.com/game/live/1");
        expect(win.url).toBe("https://www.chess.com/game/live/1");
        expect(win.start).toBe(Date.UTC(2026, 6, 20, 18, 5, 0) / 1000);
        expect(win.rating).toBe(1512);
        expect(win.opp).toBe(1498);
        expect(win.oppName).toBe("Rival1");
        expect(win.rated).toBe(true);
        expect(win.color).toBe("w");
        expect(win.timeClass).toBe("blitz");
        expect(win.timeControl).toEqual({ base: 180, inc: 0 });
        expect(win.eco).toBe("B01");
        expect(win.openingName).toBe("Scandinavian Defense Mieses Kotroc Variation");
        expect(win.pgn).toBe(CHESSCOM_PGN);

        const timeoutLoss = games[2];
        expect(timeoutLoss.color).toBe("b");
        expect(timeoutLoss.timeControl).toEqual({ base: 180, inc: 2 });
        expect(timeoutLoss.start).toBeNull();
        expect(timeoutLoss.eco).toBeNull();
        expect(timeoutLoss.pgn).toBeNull();

        // Missing opponent rating stays null.
        expect(games[0].opp).toBeNull();
        expect(games[0].oppName).toBe("Rival4");
        // Casual game kept under "both".
        expect(games[3].rated).toBe(false);
    });

    it("applies the rated/casual filters", async () => {
        const nowSec = Math.floor(Date.now() / 1000);
        stubChessComFetch(nowSec);
        const rated = await fetchStatsGames({
            source: "chesscom",
            username: "StatsGuy",
            timeClass: "blitz",
            ratedFilter: "rated",
            maxGames: 100,
            maxDays: 30,
            monthsCap: 2,
        });
        expect(rated.map((game) => game.rated)).toEqual([true, true, true]);

        stubChessComFetch(nowSec);
        const casual = await fetchStatsGames({
            source: "chesscom",
            username: "StatsGuy",
            timeClass: "blitz",
            ratedFilter: "casual",
            maxGames: 100,
            maxDays: 30,
            monthsCap: 2,
        });
        expect(casual.map((game) => game.url)).toEqual(["https://www.chess.com/game/live/3"]);
    });

    it("normalizes daily games with the 1/86400 time control", async () => {
        const nowSec = Math.floor(Date.now() / 1000);
        stubChessComFetch(nowSec);
        const games = await fetchStatsGames({
            source: "chesscom",
            username: "StatsGuy",
            timeClass: "daily",
            ratedFilter: "both",
            maxGames: 100,
            maxDays: 30,
            monthsCap: 2,
        });
        expect(games).toHaveLength(1);
        expect(games[0].timeClass).toBe("daily");
        expect(games[0].timeControl).toEqual({ base: 86400, inc: 0 });
        // I won because the opponent abandoned.
        expect(games[0].termination).toBe("abandon");
        expect(games[0].result).toBe("win");
    });

    it("keeps only the most recent maxGames", async () => {
        const nowSec = Math.floor(Date.now() / 1000);
        stubChessComFetch(nowSec);
        const games = await fetchStatsGames({
            source: "chesscom",
            username: "StatsGuy",
            timeClass: "blitz",
            ratedFilter: "both",
            maxGames: 2,
            maxDays: 30,
            monthsCap: 2,
        });
        expect(games.map((game) => game.end)).toEqual([nowSec - 6000, nowSec - 3000]);
    });
});

