        const { requests } = stubLichessFetch(nowMs);
        const rated = await fetchStatsGames({
            source: "lichess",
            username: "LichUser",
            timeClass: "blitz",
            ratedFilter: "rated",
            maxGames: 100,
            maxDays: 30,
        });
        expect(requests[0].url).toContain("rated=true");
        expect(rated.map((game) => game.id)).toEqual(["aaaa1111", "cccc3333", "dddd4444"]);
